from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any


_CENT = Decimal("0.01")


def _decimal(value: Any) -> Decimal:
    if value is None:
        return Decimal(0)
    if isinstance(value, str):
        value = value.strip()
        if not value:
            return Decimal(0)
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal(0)


def _money(value: Any) -> Decimal:
    return _decimal(value).quantize(_CENT, rounding=ROUND_HALF_UP)


def _primary_key(value: Any) -> tuple[int, Any]:
    if isinstance(value, (int, float, Decimal)) and not isinstance(value, bool):
        return (0, _decimal(value))
    if value is None:
        return (2, "")
    return (1, str(value))


def sweep(
    accounts: list[dict], orders: list[dict]
) -> tuple[list[dict], list]:
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    eligible = [
        index
        for index, account in enumerate(accounts)
        if account.get("DEL_FLG") != "Y"
        and account.get("ACCT_TYP") == "C"
    ]
    eligible.sort(
        key=lambda index: _primary_key(accounts[index].get("ACCT_ID"))
    )

    for index in eligible:
        account = accounts[index]
        acct_id = account.get("ACCT_ID")

        exposure = Decimal(0)
        for order in orders:
            if (
                order.get("DEL_FLG") != "Y"
                and order.get("ACCT_ID") == acct_id
                and order.get("STAT_CD") == "I"
            ):
                exposure += _money(order.get("TOT_AMT"))

        limit = _money(account.get("CRED_LIMIT"))
        held = account.get("CRED_HOLD") == "Y"

        if exposure > limit and not held:
            new_accounts[index]["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        if exposure <= (limit * Decimal(8) / Decimal(10)):
            if new_accounts[index].get("CRED_HOLD") == "Y":
                new_accounts[index]["CRED_HOLD"] = "N"
                audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
